import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

/**
 * Tests for {@link Sigmoid}, a scaled logistic function defined by
 * {@code f(x) = lo + (hi - lo) / (1 + exp(-x))}.
 *
 * The tests cover three entry points:
 * <ul>
 *   <li>{@link Sigmoid#value(DerivativeStructure)} for automatic differentiation,</li>
 *   <li>{@link Sigmoid#applyAsDouble(double)} for plain scalar evaluation, and</li>
 *   <li>the {@link Sigmoid.Parametric} helper used during curve fitting.</li>
 * </ul>
 */
@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class Sigmoid_ESTest extends Sigmoid_ESTest_scaffolding {

  /** Tolerance shared by all floating-point comparisons in this suite. */
  private static final double TOLERANCE = 0.01;

  /**
   * For a very large positive input the sigmoid saturates at its upper
   * asymptote, so {@code value(...)} should return the configured high value.
   */
  @Test(timeout = 4000)
  public void valueSaturatesAtUpperAsymptoteForLargeInput()  throws Throwable  {
      double lowerAsymptote = 33.182076530840796;
      double upperAsymptote = 1.2246467991473532E-16;
      Sigmoid sigmoid = new Sigmoid(lowerAsymptote, upperAsymptote);

      DerivativeStructure largeNegativeInput = new DerivativeStructure(620, 0, (-1023.143076));
      DerivativeStructure result = sigmoid.value(largeNegativeInput);

      assertEquals(lowerAsymptote, result.getValue(), TOLERANCE);
  }

  /**
   * At input {@code x = 0} the sigmoid evaluates to the midpoint between its
   * low and high values, i.e. {@code lo + (hi - lo) / 2}.
   */
  @Test(timeout = 4000)
  public void valueAtZeroIsMidpointBetweenAsymptotes()  throws Throwable  {
      double lowerAsymptote = 0.06666666666666667;
      double upperAsymptote = 0.0;
      Sigmoid sigmoid = new Sigmoid(lowerAsymptote, upperAsymptote);

      DerivativeStructure zeroInput = new DerivativeStructure(4, 4, 0.0);
      DerivativeStructure result = sigmoid.value(zeroInput);

      assertEquals(0.03333333333333333, result.getValue(), TOLERANCE);
  }

  /**
   * {@code Parametric.gradient} requires exactly two parameters (low, high);
   * passing a one-element array must be rejected with a dimension-mismatch
   * exception ("1 != 2").
   */
  @Test(timeout = 4000)
  public void parametricGradientRejectsWrongParameterCount()  throws Throwable  {
      Sigmoid.Parametric parametric = new Sigmoid.Parametric();
      double[] tooFewParameters = new double[1];

      try {
        parametric.gradient((-743.321909624), tooFewParameters);
        fail("Expecting exception: RuntimeException");
      } catch(RuntimeException e) {
         // Dimension mismatch: 1 parameter supplied, 2 expected.
         verifyException("org.apache.commons.math4.legacy.analysis.function.Sigmoid$Parametric", e);
      }
  }

  /**
   * {@code Parametric.gradient} must reject a {@code null} parameter array
   * with a NullPointerException ("null is not allowed").
   */
  @Test(timeout = 4000)
  public void parametricGradientRejectsNullParameters()  throws Throwable  {
      Sigmoid.Parametric parametric = new Sigmoid.Parametric();

      try {
        parametric.gradient(1.0, (double[]) null);
        fail("Expecting exception: NullPointerException");
      } catch(NullPointerException e) {
         // A null parameter array is not allowed.
         verifyException("org.apache.commons.math4.legacy.analysis.function.Sigmoid$Parametric", e);
      }
  }

  /** The no-argument constructor builds a default sigmoid without error. */
  @Test(timeout = 4000)
  public void defaultConstructorSucceeds()  throws Throwable  {
      Sigmoid sigmoid = new Sigmoid();
  }

  /**
   * Scalar evaluation via {@link Sigmoid#applyAsDouble(double)} returns the
   * expected logistic value for a finite input.
   */
  @Test(timeout = 4000)
  public void applyAsDoubleEvaluatesScalarInput()  throws Throwable  {
      Sigmoid sigmoid = new Sigmoid(0.06666666666666667, 0.0);

      double result = sigmoid.applyAsDouble(0.625);

      assertEquals(0.023243009022263054, result, TOLERANCE);
  }

  /**
   * {@code Parametric.gradient} returns the partial derivatives with respect
   * to the low and high parameters for a given input.
   */
  @Test(timeout = 4000)
  public void parametricGradientReturnsPartialDerivatives()  throws Throwable  {
      Sigmoid.Parametric parametric = new Sigmoid.Parametric();
      double[] parameters = new double[2];

      double[] gradient = parametric.gradient((-20.0), parameters);

      assertArrayEquals(new double[] {0.9999999979388464, 2.0611536181902037E-9}, gradient, TOLERANCE);
  }

  /**
   * {@code Parametric.value} evaluates the sigmoid for the supplied parameters;
   * with zero parameters and a zero input the result is zero.
   */
  @Test(timeout = 4000)
  public void parametricValueEvaluatesWithGivenParameters()  throws Throwable  {
      Sigmoid.Parametric parametric = new Sigmoid.Parametric();
      double[] parameters = new double[2];

      double result = parametric.value(0.0, parameters);

      assertEquals(0.0, result, TOLERANCE);
  }
